660	        VisitDto visitDto = visitMapper.toVisitDto(visit);
661	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
662	            .buildAndExpand(visit.getId()).toUri());
663	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
664	    }
665	
666	
667	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
668	    @Override
669	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
670	        Owner owner = this.clinicService.findOwnerById(ownerId);
671	        if (owner != null) {
672	            Pet pet = owner.getPet(petId);
673	            if (pet != null) {
674	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
675	            }
676	        }
677	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
678	    }
