265	        }
266	        String digits = telephone.substring(1);
267	        int countryCodeLength = countryCodeLength(digits);
268	        String countryCode = digits.substring(0, countryCodeLength);
269	        String national = digits.substring(countryCodeLength);
270	        StringBuilder grouped = new StringBuilder("+").append(countryCode);
271	        for (int i = 0; i < national.length(); i += 3) {
272	            grouped.append(' ').append(national, i, Math.min(i + 3, national.length()));
273	        }
274	        return grouped.toString();
275	    }
276	
277	    /**
278	     * Determines the length of the country-code segment of an E.164 number's digits (its digits
279	     * without the leading {@code '+'}): 1 for the NANP ({@code '+1'}) and 2 otherwise (e.g. Australia's
280	     * {@code '+61'}), mirroring the country codes the application normalises to.
281	     */
282	    private int countryCodeLength(String digits) {
283	        return digits.startsWith("1") ? 1 : 2;
284	    }
285	
286	    /**
287	     * Formats an owner's display name as {@code "LastName, FirstName"} from the stored names.
288	     */
