298	     * (e.g. {@code "DR Franklin"}) when a title is present, or just the last name when no title
299	     * is given (null or blank). Returns {@code null} when the owner is {@code null}.
300	     */
301	    default String formatSalutation(Owner owner) {
302	        if (owner == null) {
303	            return null;
304	        }
305	        String title = owner.getTitle();
306	        if (title == null || title.isBlank()) {
307	            return owner.getLastName();
308	        }
309	        return title + " " + owner.getLastName();
310	    }
311	
312	    /**
313	     * Formats an owner's initials as the upper-cased first letters of the first and last
314	     * names, dot-separated with a trailing dot (e.g. {@code "J.S."}).
315	     */
316	    default String formatInitials(Owner owner) {
317	        if (owner == null) {
318	            return null;
319	        }
320	        return initial(owner.getFirstName()) + initial(owner.getLastName());
321	    }
322	
323	    private String initial(String name) {
324	        if (name == null || name.isEmpty()) {
325	            return "";
326	        }
327	        return Character.toUpperCase(name.charAt(0)) + ".";
328	    }
