341	        OwnerPageDto ownerPageDto = new OwnerPageDto();
342	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
343	        ownerPageDto.setPage(ownerPage.getNumber());
344	        ownerPageDto.setSize(ownerPage.getSize());
345	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
346	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
347	        return ownerPageDto;
348	    }
